function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[A-Za-z]+$/.test(s)) return 's may contain only English letters.';
  return null;
}

