function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 10);
  const letters = size === 'large' && rand() < 0.3 ? 'abcdefghijklmnopqrstuvwxyz' : 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const pick = () => {
    const ch = letters[Math.floor(rand() * letters.length)];
    return rand() < 0.5 ? ch : ch.toUpperCase();
  };
  const flip = ch => ch === ch.toLowerCase() ? ch.toUpperCase() : ch.toLowerCase();
  // Build from random letters and nested clashing pairs, so that removals cascade.
  const parts = [];
  let length = 0;
  while (length < n) {
    if (n - length >= 2 && rand() < 0.5) {
      const depth = 1 + Math.floor(rand() * Math.min(5, (n - length) / 2));
      const opening = Array.from({ length: depth }, pick);
      const closing = opening.map(flip).reverse();
      parts.push(opening.join('') + closing.join(''));
      length += 2 * depth;
    } else {
      parts.push(pick());
      length += 1;
    }
  }
  return [parts.join('').slice(0, n)];
}
